import { test, expect } from '@playwright/test';

test.describe('Multi-Step Form Progress Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/multi-step-form');
  });

  test('should display progress indicator and update as user completes steps', async ({ page }) => {
    // Verify initial state: progress indicator is empty
    const progressIndicator = page.getByTestId('progress-indicator');
    await expect(progressIndicator).toBeVisible();
    await expect(progressIndicator).toHaveValue('0%');

    // Navigate to first step
    const firstStepButton = page.getByRole('button', { name: /step 1/i });
    await firstStepButton.click();

    // Verify first step is visible
    const firstStepForm = page.getByTestId('step-form-1');
    await expect(firstStepForm).toBeVisible();

    // Verify progress indicator shows 25%
    await expect(progressIndicator).toHaveValue('25%');

    // Fill out first step form
    const firstStepInput = page.getByLabel(/first name/i);
    await firstStepInput.fill('John');

    const firstStepSubmitButton = page.getByRole('button', { name: /submit/i });
    await firstStepSubmitButton.click();

    // Verify form is submitted and progress indicator updates
    const successMessage = page.getByText(/successfully submitted step 1/i);
    await expect(successMessage).toBeVisible();

    await expect(progressIndicator).toHaveValue('50%');

    // Navigate to second step
    const secondStepButton = page.getByRole('button', { name: /step 2/i });
    await secondStepButton.click();

    // Verify second step is visible
    const secondStepForm = page.getByTestId('step-form-2');
    await expect(secondStepForm).toBeVisible();

    // Verify progress indicator shows 75%
    await expect(progressIndicator).toHaveValue('75%');

    // Fill out second step form
    const secondStepInput = page.getByLabel(/email/i);
    await secondStepInput.fill('john@example.com');

    const secondStepSubmitButton = page.getByRole('button', { name: /submit/i });
    await secondStepSubmitButton.click();

    // Verify form is submitted and progress indicator updates
    await expect(progressIndicator).toHaveValue('100%');

    // Verify success message for second step
    await expect(successMessage).toBeVisible();

    // Navigate to third step
    const thirdStepButton = page.getByRole('button', { name: /step 3/i });
    await thirdStepButton.click();

    // Verify third step is visible
    const thirdStepForm = page.getByTestId('step-form-3');
    await expect(thirdStepForm).toBeVisible();

    // Verify progress indicator shows 100%
    await expect(progressIndicator).toHaveValue('100%');

    // Verify success message for third step
    const thirdStepSuccessMessage = page.getByText(/successfully submitted step 3/i);
    await expect(thirdStepSuccessMessage).toBeVisible();

    // Verify form is submitted and progress indicator is complete
    await expect(progressIndicator).toHaveValue('100%');
  });

  test('should handle form submission errors and display appropriate messages', async ({ page }) => {
    // Navigate to first step
    const firstStepButton = page.getByRole('button', { name: /step 1/i });
    await firstStepButton.click();

    // Verify first step form is visible
    const firstStepForm = page.getByTestId('step-form-1');
    await expect(firstStepForm).toBeVisible();

    // Fill out first step form with invalid data
    const firstStepInput = page.getByLabel(/first name/i);
    await firstStepInput.fill('Invalid Name');

    const firstStepSubmitButton = page.getByRole('button', { name: /submit/i });
    await firstStepSubmitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/please enter a valid name/i);
    await expect(errorMessage).toBeVisible();

    // Verify progress indicator does not update
    const progressIndicator = page.getByTestId('progress-indicator');
    await expect(progressIndicator).toHaveValue('25%');

    // Navigate to second step
    const secondStepButton = page.getByRole('button', { name: /step 2/i });
    await secondStepButton.click();

    // Verify second step form is visible
    const secondStepForm = page.getByTestId('step-form-2');
    await expect(secondStepForm).toBeVisible();

    // Fill out second step form with valid data
    const secondStepInput = page.getByLabel(/email/i);
    await secondStepInput.fill('john@example.com');

    const secondStepSubmitButton = page.getByRole('button', { name: /submit/i });
    await secondStepSubmitButton.click();

    // Verify form is submitted and progress indicator updates
    await expect(progressIndicator).toHaveValue('50%');

    // Verify success message for second step
    const successMessage = page.getByText(/successfully submitted step 2/i);
    await expect(successMessage).toBeVisible();

    // Navigate to third step
    const thirdStepButton = page.getByRole('button', { name: /step 3/i });
    await thirdStepButton.click();

    // Verify third step form is visible
    const thirdStepForm = page.getByTestId('step-form-3');
    await expect(thirdStepForm).toBeVisible();

    // Fill out third step form with invalid data
    const thirdStepInput = page.getByLabel(/password/i);
    await thirdStepInput.fill('Short');

    const thirdStepSubmitButton = page.getByRole('button', { name: /submit/i });
    await thirdStepSubmitButton.click();

    // Verify error message is displayed
    const thirdStepErrorMessage = page.getByText(/password must be at least 8 characters/i);
    await expect(thirdStepErrorMessage).toBeVisible();

    // Verify progress indicator does not update
    await expect(progressIndicator).toHaveValue('75%');

    // Verify form is not submitted
    await expect(page).toHaveURL(/step-2/);
  });
});
